import{_ as a,o as e,c as t,a3 as p}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/09-欲望低下、能力低下者即“下流”.md","filePath":"books/xialiu-shehui/09-欲望低下、能力低下者即“下流”.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/09-欲望低下、能力低下者即“下流”.md"};function s(i,_,r,n,l,d){return e(),t("div",null,[..._[0]||(_[0]=[p('<h2 id="欲望低下、能力低下者即-下流" tabindex="-1">欲望低下、能力低下者即“下流” <a class="header-anchor" href="#欲望低下、能力低下者即-下流" aria-label="Permalink to &quot;欲望低下、能力低下者即“下流”&quot;">​</a></h2><p>“下流社会”又是指什么样的社会呢？在具体描述之前，有必要比较详细地了解一下国民生活的概况，尤其是必须了解国民的消费模式和生活样式。</p><p>不过遗憾的是，经济学家或社会学家所进行的阶层研究中却罕有关于消费的专门研究。鉴于此，笔者将根据2004年11月和2005年5月所进行的独自调查，来对阶层意识中的消费行为的差异进行分析。本书从第三章起，将对上述调查结果进行概略的介绍，从中可以清晰地看到，在目前年龄约三十多岁、被称为“团块次代”的这一代年轻人中所显现出来的“下流化”倾向。</p><p>由于这一代人群人口众多，他们如何行为，其社会意识如何，对于社会及消费的发展趋势必将产生莫大的影响。在后面我们将会看到，这一世代中，尤其是在这一世代的男性当中，生活水平居于“中下流”或者“下流”的人数特别多。</p><p>阶层意识不单单是由一个人的收入以及资产等所决定的，它还取决于这个人的学历、职业等因素，而且不仅仅受到个人收入、资产、学历、职业等因素的影响，它还受到父母的以上诸因素的影响。更令人感兴趣的是，调查结果还显示，个人的性格、价值观、兴趣、幸福感、家庭关系等也深深地介入到阶层意识的形成过程中。</p><p>本书一开头的“下流指数测试”正是基于这些调查结果而设计的。从测试所包含的项目中也可以看出，所谓“下流”不仅仅是收入的低下，其人际沟通能力、生活能力、工作热情、学习意愿、消费欲望等也全都较之一般人更为低下，概而言之，即是对于全盘人生热情低下，其结果直接导致收入很难得到提高，单身的比例也极高。在这类人群中，疲疲沓沓走路、松松垮垮生活的人不在少数，因为这样的生活态度毕竟来得轻松些。</p><p>团块次代是日本进入中流社会之后出生的第一代人，因此自团块次代以后的世代都没有目睹过悬殊的社会贫富差异。在都市郊外的新兴住宅小区里，年龄相仿、收入相近的人，居住在式样雷同的房子里，开着相似的汽车，所有人看上去都差不多，一副小康即安的样子，而这被视为是理所当然的事情。因而从根本上就缺乏从“下流”向“中流”提升自己的志向，从“中流的中层”向“中流的上层”靠拢的意欲也极其淡薄，甚至从来就没有考虑过会不会从“中流”跌至“下流”。他们就是在这样的环境中长大起来的。</p><p>为什么人类要不断攀登险峰？是因为期待着险峰之颠有令人惊奇的美景。倘若已经攀登至七成的高度，并且明知险峰之巅根本没有什么美景，而七成高度的地方却是山花烂漫、乱云飞渡、美不胜收，那么谁也不愿花费气力去攀登峰顶。下流阶层的不求上进就跟登山是一个道理。</p><p>如今，廉价商店里以低得令人讶异、不禁怀疑自己眼睛的低廉价格出售各色商品，名家演奏的古典音乐名曲CD只售100日元。这样的时代，松松垮垮照样能够生活，努力工作的人却可能会被讥讽为傻瓜，因此，便有越来越多的人松松垮垮地生活着。</p><p>然而，以团块次代为中心的年轻世代今后将继续生活下去的这个社会，已经与以往的社会迥然有异了。同一届大学毕业的人，在同一家公司工作，刚过三十来岁收入差距却已经成倍拉开了。说得极端些，现在的社会只有少数的企业精英分子，却拥有大量无固定职业的自由打工者、失业者以及无业者。当整个社会形成一股上升气流时，即使个人缺少上升意欲，也可以在不知不觉间随大气流一同上升，而当整个社会不再处于上升期的时候，只有上升意欲极其强烈并且拥有一定能力的人才能最终得到上升，不具备上述动力的人便只有跌落了。</p><p>面对这样的时代，年轻的世代其价值观、生活、消费今后将会发生怎样的变化？这便是本书所要探讨的课题。</p>',11)])])}const u=a(o,[["render",s]]);export{h as __pageData,u as default};
